const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'normalize' && mode[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

class Fail extends Error {}

function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  const m = /^(?:([^/?#]*):)?/.exec(s)
  if (m[1] !== undefined) r.scheme = m[1]
  s = s.slice(m[0].length)
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    r.authority = e < 0 ? s.slice(2) : s.slice(2, 2 + e)
    s = e < 0 ? '' : s.slice(2 + e)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

function splitAuth(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const c = hp.indexOf(':', hp.lastIndexOf(']') + 1)
  return c >= 0 ? { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) } : { userinfo, host: hp, port: undefined }
}

function pct(s, what) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`the ${what} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function removeDots(p) {
  let inp = p, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let auth
  if (r.authority !== undefined) {
    const a = splitAuth(r.authority)
    const userinfo = a.userinfo === undefined ? undefined : pct(a.userinfo, 'userinfo')
    const host = lower(pct(a.host, 'host'))
    let port = a.port
    if (port === '' || (scheme !== undefined && DEFAULTS[scheme] === port)) port = undefined
    auth = (userinfo === undefined ? '' : userinfo + '@') + host + (port === undefined ? '' : ':' + port)
  } else if (/%(?![0-9A-Fa-f]{2})/.test(r.path)) { /* checked below */ }
  let path = removeDots(pct(r.path, 'path'))
  const query = r.query === undefined ? undefined : pct(r.query, 'query')
  const fragment = r.fragment === undefined ? undefined : pct(r.fragment, 'fragment')
  if (auth !== undefined && path === '') path = '/'
  return (scheme === undefined ? '' : scheme + ':') + (auth === undefined ? '' : '//' + auth) + path +
    (query === undefined ? '' : '?' + query) + (fragment === undefined ? '' : '#' + fragment)
}

function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref); t.path = removeDots(ref.path)
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref); t.scheme = base.scheme; t.path = removeDots(ref.path)
  } else {
    t.scheme = base.scheme; t.authority = base.authority; t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
    }
  }
  return t
}

const input = require_stdin()
function require_stdin() {
  return require('node:fs').readFileSync(0, 'utf8')
}
