import('node:fs').then(({ readFileSync }) => {
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      try {
        if (mode[0] === 'normalize') out.push(normalize(parse(line)))
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const base = parse(line.slice(0, sp))
          if (base.scheme === undefined) throw new Fail('the base has no scheme')
          out.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${idx + 1}: ${e.message}`)
        throw e
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
})
