{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cost = new Map()
const depLines = []
const NAME = /^[A-Za-z0-9_.-]+$/
for (let i = 0; i < lines.length; i++) {
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
const deps = new Map([...cost.keys()].map((k) => [k, new Set()]))
for (const w of depLines) {
  for (const x of w) if (!cost.has(x)) fail(`error: unknown task ${x}`)
  for (const d of w.slice(1)) deps.get(w[0]).add(d)
}
const names = [...cost.keys()].sort()
const sdeps = new Map(names.map((k) => [k, [...deps.get(k)].sort()]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of sdeps.get(u)) {
    const s = state.get(v)
    if (s === 1) return [...stack.slice(stack.indexOf(v)), v]
    if (!s) {
      const c = dfs(v)
      if (c) return c
    }
  }
  stack.pop()
  state.set(u, 2)
  return null
}
for (const u of names) {
  if (!state.get(u)) {
    const c = dfs(u)
    if (c) fail('error: cycle: ' + c.join(' -> '), 3)
  }
}

const start = new Map(), finish = new Map(), depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of sdeps.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
names.forEach(calc)
let total = 0n
for (const u of names) if (finish.get(u) > total) total = finish.get(u)

const out = []
if (mode === 'waves') {
  const ws = []
  for (const u of names) (ws[depth.get(u)] ??= []).push(u)
  ws.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const u of names) out.push(`${u} start=${start.get(u)} finish=${finish.get(u)} depth=${depth.get(u)}`)
  out.push(`total ${total}`)
} else {
  const rdeps = new Map(names.map((k) => [k, []]))
  for (const u of names) for (const v of sdeps.get(u)) rdeps.get(v).push(u)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const r of rdeps.get(u)) { const p = pr(r); if (p > m) m = p }
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? 0 : prio.get(a) > prio.get(b) ? -1 : 1) || (a < b ? -1 : a > b ? 1 : 0))
  const done = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n, mk = 0n
  while (true) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((u) => !done.has(u) && sdeps.get(u).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + cost.get(task)
      done.set(task, f)
      freeAt[w] = f
      runs[w].push(`${task}@${t}-${f}`)
      if (f > mk) mk = f
    }
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${mk}`)
}
process.stdout.write(out.join('\n') + '\n')
EOF
