    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') {
      this.i++
      const items = []
      for (;;) {
        if (this.atEnd()) fail('unterminated array')
        if (this.s[this.i] === ']') { this.i++; break }
        items.push(this.value(prefix + '[]'))
        if (this.atEnd()) fail('unterminated array')
        const d = this.s[this.i]
        if (d === ',') { this.i++; continue }
        if (d === ']') { this.i++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      this.i++
      const tab = newTable()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.s[this.i] === '}') { this.i++; return tab }
      for (;;) {
        if (this.atEnd()) fail('unterminated inline table')
        const keys = this.dotted()
        this.ws()
        if (this.s[this.i] !== '=') fail('expected = in an inline table')
        this.i++
        const v = this.value(join(prefix, keys))
        assign(tab, prefix, keys, v)
        if (this.atEnd()) fail('unterminated inline table')
        const d = this.s[this.i]
        if (d === ',') { this.i++; continue }
        if (d === '}') { this.i++; break }
        fail('unterminated inline table')
      }
      return tab
    }
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
}

const join = (prefix, keys) => (prefix ? [prefix, ...keys] : keys).join('.')
const sub = (prefix, k) => (prefix ? prefix + '.' + k : k)

// Walk `keys` (all but the last) from `tab`, creating tables.
function walk(tab, prefix, keys) {
  let path = prefix
  for (const k of keys) {
    path = sub(path, k)
    let n = tab.map.get(k)
    if (!n) { n = newTable(); tab.map.set(k, n) }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') fail(path + ' is not a table')
    tab = n
  }
  return tab
}

function assign(tab, prefix, keys, v) {
  const t = walk(tab, prefix, keys.slice(0, -1))
  const last = keys[keys.length - 1]
  if (t.map.has(last)) fail('key ' + join(prefix, keys) + ' is defined twice')
  t.map.set(last, v)
}

function header(root, p) {
  p.i++
  const aot = p.s[p.i] === '['
  if (aot) p.i++
  p.ws()
  const keys = p.dotted()
  p.ws()
  if (p.i >= p.s.length || p.s[p.i] === '#' || p.s[p.i] === ';') fail('unterminated table header')
  if (p.s[p.i] !== ']') fail('unterminated table header')
  p.i++
  if (aot) {
    if (p.s[p.i] !== ']') {
      if (p.atEnd()) fail('unterminated table header')
      fail('trailing text after a table header')
    }
    p.i++
  }
  if (!p.atEnd()) fail('trailing text after a table header')
  const full = keys.join('.')
  const parent = walk(root, '', keys.slice(0, -1))
  const last = keys[keys.length - 1]
  const n = parent.map.get(last)
  if (aot) {
    if (!n) {
      const a = { t: 'array', items: [], aot: true }
      parent.map.set(last, a)
      const nt = newTable()
      a.items.push(nt)
      return [nt, full]
    }
    if (n.t !== 'array' || !n.aot) fail(full + ' is not an array of tables')
    const nt = newTable()
    n.items.push(nt)
    return [nt, full]
  }
  if (!n) {
    const nt = newTable()
    nt.made = true
    parent.map.set(last, nt)
    return [nt, full]
  }
  if (n.t !== 'table') fail(full + ' is not a table')
  if (n.made) fail('table ' + full + ' is defined twice')
  n.made = true
  return [n, full]
}

function parseDoc(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root, curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new LineParser(lines[n])
      p.ws()
      const c = p.s[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') { [cur, curPath] = header(root, p); continue }
      const keys = p.dotted()
      p.ws()
      if (p.s[p.i] !== '=') fail('expected key = value')
      p.i++
      const v = p.value(join(curPath, keys))
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e instanceof ParseError) throw new ParseError(`line ${n + 1}: ${e.message}`)
      throw e
    }
  }
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < x.length && i < y.length; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n.map)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keyLines(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.map)) {
      const c = n.map.get(k), p = path ? path + '.' + k : k
      out.push(p + ' ' + c.t)
      keyLines(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      keyLines(c, p, out)
    })
  }
}

let output
try {
  const root = parseDoc(readFileSync(0, 'utf8'))
  if (mode === 'json') output = toJson(root, 0) + '\n'
  else {
    const out = []
    keyLines(root, '', out)
    output = out.map((l) => l + '\n').join('')
  }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
process.stdout.write(output)
