{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parser.js'
import { Sheet, formatValue } from './eval.js'
import { parseAddress, formatAddress, compareKeys } from './address.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const token = m[0]
  const rest = line.slice(token.length).replace(/^[ \t]+/, '')
  const addr = parseAddress(token)
  if (!addr) fail(`error: line ${n}: invalid cell address ${token}`)
  if (cells.has(addr.key)) fail(`error: line ${n}: cell ${formatAddress(addr.key)} is declared twice`)
  cells.set(addr.key, rest)
})

const keys = [...cells.keys()].sort(compareKeys)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const k of keys) out.push(`${formatAddress(k)}=${formatValue(sheet.get(k))}`)
} else {
  for (const k of keys) {
    const content = cells.get(k)
    let deps = []
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (ast) {
        const set = new Set()
        collect(ast, set)
        deps = [...set].sort(compareKeys)
      }
    }
    out.push(`${formatAddress(k)}:` + deps.map((d) => ' ' + formatAddress(d)).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))

function collect(node, set) {
  switch (node.type) {
    case 'ref':
      if (node.addr) set.add(node.addr.key)
      break
    case 'range':
      if (node.from && node.to) {
        const c1 = Math.min(node.from.col, node.to.col)
        const c2 = Math.max(node.from.col, node.to.col)
        const r1 = Math.min(node.from.row, node.to.row)
        const r2 = Math.max(node.from.row, node.to.row)
        for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) set.add(c * 1000 + r)
      }
      break
    case 'bin':
      collect(node.l, set)
      collect(node.r, set)
      break
    case 'un':
      collect(node.e, set)
      break
    case 'call':
      node.args.forEach((a) => collect(a, set))
      break
  }
}
"}

{"file_path":"src/address.js","content":"// Cell key = col * 1000 + row, with col 1..702.
export function parseAddress(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col =
    letters.length === 1
      ? letters.charCodeAt(0) - 64
      : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
  return { col, row, key: col * 1000 + row }
}

export function formatAddress(key) {
  const col = Math.floor(key / 1000)
  const row = key % 1000
  let letters
  if (col <= 26) letters = String.fromCharCode(64 + col)
  else {
    const c = col - 27
    letters = String.fromCharCode(65 + Math.floor(c / 26)) + String.fromCharCode(65 + (c % 26))
  }
  return letters + row
}

export function compareKeys(a, b) {
  return a - b
}
"}

{"file_path":"src/parser.js","content":"import { parseAddress } from './address.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: m[0] })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the text.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const FAIL = new Error('parse')

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { type: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw FAIL
    const tk = toks[p++]
    if (tk.t === 'num') return { type: 'num', v: Number(tk.v) }
    if (tk.t === 'op') {
      if (tk.v === '(') {
        const e = comparison()
        if (!isOp(')')) throw FAIL
        p++
        return e
      }
      throw FAIL
    }
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(comparison())
          if (isOp(',')) {
            p++
            continue
          }
          if (isOp(')')) {
            p++
            break
          }
          throw FAIL
        }
      }
      return { type: 'call', name: tk.v.toUpperCase(), args }
    }
    const up = tk.v.toUpperCase()
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') throw FAIL
      const w2 = toks[p++].v
      if (isOp('(')) throw FAIL
      return { type: 'range', from: parseAddress(tk.v), to: parseAddress(w2) }
    }
    if (up === 'TRUE') return { type: 'bool', v: true }
    if (up === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', addr: parseAddress(tk.v) }
  }

  try {
    const ast = comparison()
    if (p !== toks.length) return null
    return ast
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parser.js'

const ERR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const num = (v) => ({ t: 'n', v })
const bool = (v) => ({ t: 'b', v })
const err = (v) => ({ t: 'e', v })

export function formatValue(val) {
  switch (val.t) {
    case 'n':
      return String(Number(val.v.toPrecision(10)))
    case 'b':
      return val.v ? 'TRUE' : 'FALSE'
    default:
      return val.v
  }
}

function toNum(val) {
  if (val.t === 'n') return val
  if (val.t === 'b') return num(val.v ? 1 : 0)
  if (val.t === 'e') return val
  return err('#VALUE!')
}

function fin(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}

function cmpStr(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cmpStr(a.v, b.v)
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  get(key) {
    if (!this.cells.has(key)) return num(0)
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    const r = this.compute(this.cells.get(key))
    this.busy.delete(key)
    this.memo.set(key, r)
    return r
  }

  compute(content) {
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast) return err('#ERR!')
      return this.ev(ast)
    }
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERR_TOKENS.has(content)) return err(content)
    return { t: 's', v: content }
  }

  ev(node) {
    switch (node.type) {
      case 'num':
        return num(node.v)
      case 'bool':
        return bool(node.v)
      case 'ref':
        return node.addr ? this.get(node.addr.key) : err('#REF!')
      case 'range':
        return err('#ERR!')
      case 'un': {
        const v = toNum(this.ev(node.e))
        if (v.t === 'e') return v
        return num(node.op === '-' ? -v.v : v.v)
      }
      case 'bin':
        return this.bin(node)
      case 'call':
        return this.call(node)
    }
  }

  bin(node) {
    const l = this.ev(node.l)
    if (l.t === 'e') return l
    const r = this.ev(node.r)
    if (r.t === 'e') return r
    const op = node.op
    if (['=', '<>', '<', '<=', '>', '>='].includes(op)) {
      const c = compare(l, r)
      switch (op) {
        case '=': return bool(c === 0)
        case '<>': return bool(c !== 0)
        case '<': return bool(c < 0)
        case '<=': return bool(c <= 0)
        case '>': return bool(c > 0)
        default: return bool(c >= 0)
      }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (op) {
      case '+': return fin(a.v + b.v)
      case '-': return fin(a.v - b.v)
      case '*': return fin(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
      default: return fin(Math.pow(a.v, b.v))
    }
  }

  call(node) {
    const { name, args } = node
    const n = args.length
    if (name === 'IF') {
      if (n !== 3) return err('#ERR!')
      const c = this.ev(args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return this.ev(args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (n !== 1) return err('#ERR!')
      const v = toNum(this.ev(args[0]))
      if (v.t === 'e') return v
      return num(Math.abs(v.v))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (n < 1) return err('#ERR!')
    const vals = []
    for (const a of args) {
      if (a.type === 'range') {
