      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          let k = j + 1
          if (s[k] === '+' || s[k] === '-') k++
          if (isDigit(s[k])) j = run(k, isDigit)
        }
      }
      if (!ok || isIdPart(s[j])) {
        while (isIdPart(s[j])) j++
        throw new ScanError(tl, tc, `invalid number ${s.slice(i, j).join('')}`)
      }
      const text = s.slice(i, j).join('')
      advTo(j)
      tokens.push({ line: tl, col: tc, kind: 'number', text })
      continue
    }
    if (c === '"') {
      adv()
      let value = ''
      for (;;) {
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        const d = s[i]
        if (d === '"') {
          adv()
          break
        }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') {
          value += adv()
          continue
        }
        const el = line
        const ec = col
        adv()
        if (i >= n) throw new ScanError(tl, tc, 'unterminated string')
        const e = s[i]
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') value += '\n'
        else if (e === 't') value += '\t'
        else if (e === 'r') value += '\r'
        else if (e === '\\') value += '\\'
        else if (e === '"') value += '"'
        else if (e === '0') value += '\0'
        else if (e === 'x') {
          if (!isHex(s[i + 1]) || !isHex(s[i + 2])) throw bad()
          value += String.fromCodePoint(parseInt(s[i + 1] + s[i + 2], 16))
          adv()
          adv()
        } else if (e === 'u') {
          if (s[i + 1] !== '{') throw bad()
          let j = i + 2
          let h = ''
          while (isHex(s[j])) h += s[j++]
          if (h === '' || s[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          value += String.fromCodePoint(cp)
          advTo(j)
        } else throw bad()
        adv()
      }
      tokens.push({ line: tl, col: tc, kind: 'string', value })
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      adv()
      adv()
      tokens.push({ line: tl, col: tc, kind: 'punct', text: two })
      continue
    }
    if (PUNCT1.has(c)) {
      adv()
      tokens.push({ line: tl, col: tc, kind: 'punct', text: c })
      continue
    }
    throw new ScanError(tl, tc, `unexpected character ${c}`)
  }
  return tokens
}
