import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // consume a run of digits (per pred) with single underscores between digits
  const run = (pred) => {
    let out = ''
    while (i < n) {
      if (pred(s[i])) out += adv()
      else if (s[i] === '_' && out !== '' && pred(s[i + 1])) out += adv()
      else break
    }
    return out
  }

  while (i < n) {
    const c = s[i]
    const l = line, cl = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(l, cl, 'unterminated block comment')
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(l, cl, 'unterminated string')
      adv()
      tokens.push([l, cl, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      let w = ''
      while (i < n && isIdChar(s[i])) w += adv()
      tokens.push([l, cl, KEYWORDS.has(w) ? 'keyword' : 'ident', w])
      continue
    }
    if (isDigit(c)) {
      let t = ''
      const p = (s[i + 1] || '').toLowerCase()
      let bad = false
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        t += adv(); t += adv()
        const pred = p === 'x' ? isHex : p === 'b' ? isBin : isOct
        const d = run(pred)
        t += d
        if (d === '') bad = true
      } else {
        t += run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { t += adv(); t += run(isDigit) }
        if (s[i] === 'e' || s[i] === 'E') {
          const a = s[i + 1], b = s[i + 2]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(b))) {
            t += adv()
            if (!isDigit(s[i])) t += adv()
            t += run(isDigit)
          }
        }
      }
      if (bad || (i < n && isIdChar(s[i]))) {
        while (i < n && isIdChar(s[i])) t += adv()
        throw new ScanError(l, cl, `invalid number ${t}`)
      }
      tokens.push([l, cl, 'number', t])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(l, cl, 'unterminated string')
        const ch = s[i]
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch === '"') { adv(); break }
        if (ch !== '\\') { v += adv(); continue }
        const el = line, ec = col
        adv()
        if (i >= n) throw new ScanError(l, cl, 'unterminated string')
        const e = adv()
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) v += simple[e]
        else if (e === 'x') {
          if (isHex(s[i]) && isHex(s[i + 1])) {
            v += String.fromCharCode(parseInt(s[i] + s[i + 1], 16)); adv(); adv()
          } else throw new ScanError(el, ec, 'invalid escape \\x')
        } else if (e === 'u') {
          let j = i, ok = s[j] === '{'
          let h = ''
          if (ok) {
            j++
            while (isHex(s[j])) h += s[j++]
            ok = h !== '' && s[j] === '}' && parseInt(h, 16) <= 0x10ffff
          }
          if (!ok) throw new ScanError(el, ec, 'invalid escape \\u')
          v += String.fromCodePoint(parseInt(h, 16))
          while (i <= j) adv()
        } else throw new ScanError(el, ec, `invalid escape \\${e}`)
      }
      tokens.push([l, cl, 'string', JSON.stringify(v)])
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT2.has(two)) { adv(); adv(); tokens.push([l, cl, 'punct', two]); continue }
    if (PUNCT1.has(c)) { adv(); tokens.push([l, cl, 'punct', c]); continue }
    throw new ScanError(l, cl, `unexpected character ${c}`)
  }
  return tokens
}

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let tokens
try {
  tokens = scan(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'tokens') {
  for (const [l, c, k, b] of tokens) out += `${l}:${c} ${k} ${b}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t[2] === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
