import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) { super(msg); this.code = code }
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const deps = new Map()
  const used = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], BigInt(w[2]))
      deps.set(w[1], new Set())
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      used.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of used) for (const x of names) {
    if (!cost.has(x)) throw new Fail(`error: unknown task ${x}`)
  }
  for (const [name, ...ds] of used) for (const d of ds) deps.get(name).add(d)
  const sorted = new Map()
  for (const [k, s] of deps) sorted.set(k, [...s].sort(cmp))
  return { cost, deps: sorted, names: [...cost.keys()].sort(cmp) }
}

function findCycle({ deps, names }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of deps.get(u)) {
      const s = state.get(v)
      if (s === 1) return [...stack.slice(stack.indexOf(v)), v]
      if (!s) { const c = visit(v); if (c) return c }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }
  for (const u of names) if (!state.get(u)) { const c = visit(u); if (c) return c }
  return null
}

function schedule(g) {
  const start = new Map(), finish = new Map(), depth = new Map()
  const go = (u) => {
    if (finish.has(u)) return
    let s = 0n, d = 0
    for (const v of g.deps.get(u)) {
      go(v)
      if (finish.get(v) > s) s = finish.get(v)
      if (depth.get(v) + 1 > d) d = depth.get(v) + 1
    }
    start.set(u, s); finish.set(u, s + g.cost.get(u)); depth.set(u, d)
  }
  g.names.forEach(go)
  let total = 0n
  for (const f of finish.values()) if (f > total) total = f
  return { start, finish, depth, total }
}

function pack(g, workers) {
  const rdeps = new Map(g.names.map((n) => [n, []]))
  for (const [k, ds] of g.deps) for (const d of ds) rdeps.get(d).push(k)
  const prio = new Map()
  const p = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const v of rdeps.get(u)) { const x = p(v); if (x > m) m = x }
    prio.set(u, m + g.cost.get(u))
    return prio.get(u)
  }
  g.names.forEach(p)
  const fin = new Map()
  const pending = new Set(g.names)
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n, makespan = 0n
  for (;;) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const u of pending) {
        if (!g.deps.get(u).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(u) > prio.get(best) || (prio.get(u) === prio.get(best) && u < best)) best = u
      }
      if (best === null) break
      pending.delete(best)
      const f = t + g.cost.get(best)
      fin.set(best, f)
      freeAt[w] = f
      runs[w].push(` ${best}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (pending.size === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return runs.map((r, i) => `worker ${i}:${r.join('')}\n`).join('') + `makespan ${makespan}\n`
}

function main() {
  const a = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let workers = 0
  if (a.length === 1 && (a[0] === 'waves' || a[0] === 'explain')) {
    // ok
  } else if (a.length === 2 && a[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(a[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(a[1])
  } else throw new Fail(usage)
  const g = parse(readFileSync(0, 'utf8'))
  const cyc = findCycle(g)
  if (cyc) throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
  if (a[0] === 'pack') return pack(g, workers)
  const s = schedule(g)
  let out = ''
  if (a[0] === 'waves') {
    const waves = []
    for (const n of g.names) (waves[s.depth.get(n)] ||= []).push(n)
    waves.forEach((ns, k) => { out += `wave ${k}: ${ns.join(' ')}\n` })
  } else {
    for (const n of g.names) out += `${n} start=${s.start.get(n)} finish=${s.finish.get(n)} depth=${s.depth.get(n)}\n`
  }
  return out + `total ${s.total}\n`
}

try {
  process.stdout.write(main())
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
