  }
  function primary() {
    const t = peek()
    if (!t) bad()
    if (t.k === 'num') { p++; return { n: 'num', v: Number(t.v) } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
