        if (!/^[A-Za-z0-9_-]+$/.test(w)) err(`invalid candidate name ${w}`)
        if (seen.has(w)) err(`candidate ${w} is declared twice`)
        seen.add(w)
      }
      candidates = [...seen]
    } else if (head === 'ballot') {
      sawBallot = true
      if (words.length < 3) err('expected ballot <count> <candidate>...')
