cat > src/merge.js <<'EOF'
function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return res
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const regions = []
  let conflict = false
  let pos = 0
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) regions.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    if (group.length === 1) {
      const c = group[0]
      regions.push({ kind: c.who === 0 ? 'mine' : 'theirs', lines: (c.who === 0 ? mine : theirs).slice(c.ss, c.se) })
      continue
    }
    const baseLines = base.slice(rs, re)
    const side = (who, lines) => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return baseLines
      const minBs = Math.min(...g.map(c => c.bs)), maxBe = Math.max(...g.map(c => c.be))
      const s = Math.min(...g.map(c => c.ss)) - (minBs - rs)
      const e = Math.max(...g.map(c => c.se)) + (re - maxBe)
      return lines.slice(s, e)
    }
    const m = side(0, mine), t = side(1, theirs)
    if (same(m, t)) regions.push({ kind: 'both', lines: m })
    else if (same(m, baseLines)) regions.push({ kind: 'theirs', lines: t })
    else if (same(t, baseLines)) regions.push({ kind: 'mine', lines: m })
    else {
      conflict = true
      regions.push({ kind: 'conflict', mine: m, base: baseLines, theirs: t })
    }
  }
  if (pos < base.length) regions.push({ kind: 'stable', lines: base.slice(pos) })
  return { regions, conflict }
}
