#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const WORD = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

// Bucket tokens are stored scaled by `per` so fractions stay exact.
function makeState(policy, tick) {
  if (policy.kind === 'bucket') {
    return { units: policy.capacity * policy.per, last: tick }
  }
  return { ticks: [] }
}

function advance(policy, st, tick) {
  if (policy.kind === 'bucket') {
    const n = tick - st.last
    st.last = tick
    if (n > 0n) {
      const cap = policy.capacity * policy.per
      st.units += policy.refill * n
      if (st.units > cap) st.units = cap
    }
  } else {
    const edge = tick - policy.span
    st.ticks = st.ticks.filter((t) => t > edge)
  }
}

function allows(policy, st) {
  return policy.kind === 'bucket' ? st.units >= policy.per : BigInt(st.ticks.length) < policy.limit
}

function record(policy, st, tick) {
  if (policy.kind === 'bucket') st.units -= policy.per
  else st.ticks.push(tick)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try {
      const f = line.split(/\s+/)
      const word = f[0]
      if (word === 'bucket' || word === 'window' || word === 'route') {
        const need = word === 'bucket' ? 5 : word === 'window' ? 4 : 3
        if (word === 'route' ? f.length < 3 : f.length !== need) {
          throw new Fail(
            word === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>'
              : word === 'window' ? 'expected window <name> <limit> <span>'
                : 'expected route <prefix> <policy>...')
        }
        if (started) throw new Fail('declarations must come before the first event')
        if (word === 'route') {
